# evaluate.pyimport tensorflow as tffrom tensorflow.keras.preprocessing.image import ImageDataGeneratorfrom config import IMG_SIZE, BATCH_SIZEimport jsondef evaluate_model(model_path, test_gen):    print(f"\nEvaluating {model_path} ...")    model = tf.keras.models.load_model(model_path)    loss, acc = model.evaluate(test_gen, verbose=1)    print(f"Test Accuracy: {acc:.4f}")    return accif __name__ == "__main__":    test_datagen = ImageDataGenerator(rescale=1./255)    test_gen = test_datagen.flow_from_directory(        "data/test",        target_size=IMG_SIZE,        batch_size=BATCH_SIZE,        class_mode='sparse',        shuffle=False    )    results = {}    # Evaluate both models    results["model_resnet_style"] = evaluate_model("model_resnet_style.h5", test_gen)    results["model_efficient"] = evaluate_model("model_efficient.h5", test_gen)    print("\n=== Evaluation Results ===")    for name, acc in results.items():        print(f"{name}: {acc:.4f}")    with open("evaluation_results.json", "w") as f:        json.dump(results, f, indent=2)